package com.bank.parsepipe;

import java.util.*;
import java.util.logging.*;

public class CheckedDemo {
    private static final Logger log = Logger.getLogger("ParsePipe");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> raw = List.of("100", "200");
        ParsePipelineService service = new ParsePipelineService();

        log.info(() -> "inline try-catch: " + service.parseInline(raw));
        log.info(() -> "wrapper utility : " + service.parseWithWrapper(raw));
    }
}

// ─── checked-throwing function interface ───
@FunctionalInterface
interface CheckedFunction<T, R> {
    R apply(T t) throws Exception;   // declares checked exception
}

// ─── Would be in service/ParsePipelineService.java ───
class ParsePipelineService {
    // a method that throws a CHECKED exception
    private int parse(String s) throws Exception {
        if (!s.matches("\\d+")) throw new Exception("bad number: " + s);
        return Integer.parseInt(s);
    }

    // approach 1: try-catch INSIDE the lambda, rethrow unchecked
    List<Integer> parseInline(List<String> raw) {
        return raw.stream()
            .map(s -> {
                try { return parse(s); }
                catch (Exception e) { throw new RuntimeException(e); } // convert to unchecked
            })
            .toList();
    }

    // approach 2: reusable wrapper utility (cleaner when repeated)
    List<Integer> parseWithWrapper(List<String> raw) {
        return raw.stream()
            .map(unchecked(this::parse))   // wrapper hides the try-catch
            .toList();
    }

    // utility: CheckedFunction → ordinary Function (catch + rethrow unchecked)
    static <T, R> java.util.function.Function<T, R> unchecked(CheckedFunction<T, R> f) {
        return t -> {
            try { return f.apply(t); }
            catch (Exception e) { throw new RuntimeException(e); }
        };
    }
}
